<template>
  <div class="manager-page"><div class="page-heading"><div><div class="eyebrow">ASSESSMENT</div><h1>提交批改</h1><p>查看学生提交内容，给出分数与反馈。</p></div></div><div class="card table-card"><div class="toolbar"><el-input v-model="keyword" clearable placeholder="搜索作业或学生" style="width:280px"><template #prefix><el-icon><Search /></el-icon></template></el-input><el-select v-model="status" clearable placeholder="全部状态" style="width:140px"><el-option label="待批改" value="SUBMITTED"/><el-option label="已批改" value="GRADED"/></el-select><div class="grow"></div><span class="text-muted">共 {{filtered.length}} 份提交</span></div><el-table :data="paged" stripe><el-table-column label="学生" width="140"><template #default="{row}"><div class="user-cell"><img :src="'/images/avatars/student.svg'"/><span>{{row.userName}}</span></div></template></el-table-column><el-table-column prop="homeworkTitle" label="作业" min-width="220"/><el-table-column prop="content" label="提交说明" min-width="250" show-overflow-tooltip/><el-table-column label="附件" width="90"><template #default="{row}"><el-button v-if="row.file" text type="primary" @click="window.open(row.file)">查看</el-button><span v-else class="text-muted">无</span></template></el-table-column><el-table-column label="提交时间" width="150"><template #default="{row}">{{date(row.submitTime)}}</template></el-table-column><el-table-column label="分数" width="80"><template #default="{row}"><b class="score">{{row.score??'—'}}</b></template></el-table-column><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.status==='GRADED'?'success':'warning'" effect="plain">{{row.status==='GRADED'?'已批改':'待批改'}}</el-tag></template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button text type="primary" @click="openGrade(row)">批改</el-button></template></el-table-column></el-table><div class="pagination-wrap"><el-pagination background layout="prev,pager,next" :total="filtered.length" :page-size="8" v-model:current-page="pageNum"/></div></div><el-dialog v-model="visible" title="作业批改" width="520px"><div class="grade-title">{{form.homeworkTitle}} · {{form.userName}}</div><el-form label-position="top"><el-form-item label="分数"><el-input-number v-model="form.score" :min="0" :max="100" style="width:100%"/></el-form-item><el-form-item label="教师评语"><el-input v-model="form.comment" type="textarea" :rows="4" placeholder="给出具体、建设性的反馈"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="grade">保存批改</el-button></template></el-dialog></div>
</template>
<script setup>
import {reactive,ref,computed,onMounted} from 'vue';import request from '@/utils/request';import {ElMessage} from 'element-plus'
const data=ref([]),keyword=ref(''),status=ref(''),pageNum=ref(1),visible=ref(false),form=reactive({});const date=v=>v?String(v).replace('T',' ').slice(0,16):'';const filtered=computed(()=>data.value.filter(x=>(!status.value||x.status===status.value)&&(!keyword.value||(x.homeworkTitle+x.userName).includes(keyword.value))));const paged=computed(()=>filtered.value.slice((pageNum.value-1)*8,pageNum.value*8));const load=()=>request.get('/submit/selectAll').then(res=>{if(res.code==='200')data.value=res.data||[]});const openGrade=row=>{Object.assign(form,row);visible.value=true};const grade=()=>request.put('/submit/grade',form).then(res=>{if(res.code==='200'){ElMessage.success('批改已保存');visible.value=false;load()}else ElMessage.error(res.msg)});onMounted(load)
</script>
<style scoped>.user-cell{display:flex;align-items:center;gap:8px}.user-cell img{width:30px;height:30px;border-radius:50%}.score{color:#b27a1b}.grade-title{background:#f8f6f0;border-radius:10px;padding:13px;color:var(--primary-deep);margin-bottom:18px}</style>
